{
  "command": "git -C rpg-project remote get-url origin && git -C rpg-project status --short",
  "timeout": 30
}

{
  "command": "body=$'Kirk approved the design in the coordinating session. The design gate is satisfied, so `plan.md` may now be added to this same still-open PR. Implementation remains gated on plan approval.\\n\\n— asset-pipeline agent, on behalf of KirkDiggler'; gh api repos/KirkDiggler/rpg-project/issues/209/comments -f body=\"$body\" --jq '{id,html_url,body}'",
  "timeout": 30
}

{
  "command": "body=$'Design PR #209 passed the design gate, and work is moving to the plan gate. No implementation issue or code has started.\\n\\n— asset-pipeline agent, on behalf of KirkDiggler'; gh api repos/KirkDiggler/rpg-project/issues/208/comments -f body=\"$body\" --jq '{id,html_url,body}'",
  "timeout": 30
}

{
  "command": "expected=$'Kirk approved the design in the coordinating session. The design gate is satisfied, so `plan.md` may now be added to this same still-open PR. Implementation remains gated on plan approval.\\n\\n— asset-pipeline agent, on behalf of KirkDiggler'; actual=\"$(gh api repos/KirkDiggler/rpg-project/issues/comments/5246888262 --jq .body)\"; test \"$actual\" = \"$expected\"; test \"$(gh api repos/KirkDiggler/rpg-project/issues/comments/5246888262 --jq .html_url)\" = 'https://github.com/KirkDiggler/rpg-project/pull/209#issuecomment-5246888262'; test \"$(gh api repos/KirkDiggler/rpg-project/issues/comments/5246888262 --jq .issue_url)\" = 'https://api.github.com/repos/KirkDiggler/rpg-project/issues/209'; test \"$(gh pr view 209 --repo KirkDiggler/rpg-project --json state --jq .state)\" = 'OPEN'; printf '%s\\n' 'verified live: PR #209 comment 5246888262; exact body/signature; correct PR; PR still open'",
  "timeout": 30
}

{
  "command": "expected=$'Design PR #209 passed the design gate, and work is moving to the plan gate. No implementation issue or code has started.\\n\\n— asset-pipeline agent, on behalf of KirkDiggler'; actual=\"$(gh api repos/KirkDiggler/rpg-project/issues/comments/5246888247 --jq .body)\"; test \"$actual\" = \"$expected\"; test \"$(gh api repos/KirkDiggler/rpg-project/issues/comments/5246888247 --jq .html_url)\" = 'https://github.com/KirkDiggler/rpg-project/issues/208#issuecomment-5246888247'; test \"$(gh api repos/KirkDiggler/rpg-project/issues/comments/5246888247 --jq .issue_url)\" = 'https://api.github.com/repos/KirkDiggler/rpg-project/issues/208'; test \"$(gh issue view 208 --repo KirkDiggler/rpg-project --json state --jq .state)\" = 'OPEN'; printf '%s\\n' 'verified live: issue #208 comment 5246888247; exact body/signature; correct issue; issue still open'",
  "timeout": 30
}

{
  "command": "git -C rpg-project diff --cached --quiet && printf '%s\\n' 'verified: no staged repository changes'; git -C rpg-project status --short",
  "timeout": 30
}

